custom_css:
@media (min-width:1101px){
#evolution{display:grid!important;box-sizing:border-box!important;width:100%!important;height:auto!important;min-height:980px!important;max-height:none!important;padding:118px 0!important;align-items:center!important;align-content:center!important}
#evolution .evolution-grid{display:grid!important;grid-template-rows:auto auto!important;row-gap:48px!important;margin:0 auto!important;padding:0!important;align-content:center!important}
#evolution .roadmap-copy{margin:0!important;padding:0!important}
#evolution .roadmap-copy .eyebrow{margin:0 0 12px!important}
#evolution .roadmap-copy h2{margin:0 0 22px!important}
#evolution .roadmap-copy p:not(.eyebrow){margin:0!important}
#evolution .prototype-timeline{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;column-gap:56px!important;row-gap:42px!important;margin:0!important;padding:0!important;align-items:start!important}
#evolution .prototype-timeline li{min-height:118px!important;margin:0!important;padding:0!important;border:0!important;align-self:start!important}
#evolution .prototype-timeline li::before,#evolution .prototype-timeline li::after,#evolution::before,#evolution::after{display:none!important;content:none!important;border:0!important}
#evolution .prototype-timeline span{display:block!important;margin-bottom:10px!important;font-size:20px!important;line-height:1.2!important}
#evolution .prototype-timeline strong{display:block!important;margin-bottom:10px!important;font-size:24px!important;line-height:1.25!important}
#evolution .prototype-timeline p{max-width:300px!important;margin:0!important;font-size:18px!important;line-height:1.55!important}
#evolution .evolution-close{display:none!important;margin:0!important;padding:0!important;border:0!important}
}
@media (max-width:1100px){
#evolution{padding-top:96px!important;padding-bottom:96px!important}
#evolution::before,#evolution::after{display:none!important;content:none!important}
#evolution .prototype-timeline span{margin-bottom:10px!important;font-size:20px!important;line-height:1.2!important}
#evolution .prototype-timeline strong{margin-bottom:10px!important;font-size:24px!important;line-height:1.25!important}
#evolution .prototype-timeline p{font-size:18px!important;line-height:1.55!important}
}
#founder .founder-payment-card[data-founder-value="HALO PE10-12"]{display:none!important}
#founder .founder-payment-card::after{display:none!important;content:none!important}
#founder .founder-deposit{display:block!important;width:100%!important}
#founder .deposit-intro,#founder .founder-payment-steps,#founder .founder-payment-grid{width:min(100%,1180px)!important;max-width:1180px!important;margin-left:auto!important;margin-right:auto!important}
#founder .founder-payment-grid{display:block!important}
#founder .founder-payment-card:not([data-founder-value="HALO PE10-12"]){display:grid!important;grid-template-columns:minmax(340px,42%) minmax(0,58%)!important;gap:clamp(28px,3.2vw,48px)!important;width:100%!important;min-height:0!important;border:0!important;background:transparent!important;box-shadow:none!important;overflow:visible!important}
#founder .founder-payment-card__visual{display:none!important}
#founder .founder-payment-card__content{padding:clamp(34px,4vw,52px)!important;border:1px solid rgba(255,255,255,.25)!important;background:#0a0b0c!important}
#founder .founder-payment-title{font-size:clamp(42px,4vw,60px)!important}
#founder .founder-payment-card dl{grid-template-rows:none!important}
#founder .founder-payment-card dl>div{min-height:74px!important;padding:14px 0!important}
#founder .founder-form{box-sizing:border-box!important;width:100%!important;max-width:none!important;margin:0!important;padding:clamp(34px,4vw,52px)!important;border:1px solid rgba(255,255,255,.25)!important;background:linear-gradient(145deg,rgba(255,255,255,.045),rgba(255,255,255,.012))!important;align-content:start!important}
#founder .founder-form::before{margin-bottom:18px!important;font-size:clamp(28px,3vw,40px)!important}
#founder .founder-form label:has(select[name="Preferred rod"]){display:none!important}
#founder .founder-selection-summary{display:none!important}
#founder .founder-submit{min-height:58px!important}
#founder .founder-payment-steps{margin-top:36px!important;margin-bottom:38px!important}
#founder .halo-allocation-note{width:min(100%,1180px);margin:30px auto 0;padding-top:18px;border-top:1px solid rgba(255,255,255,.14);color:rgba(255,255,255,.48);font-size:13px;line-height:1.55}
#founder .product-viewer-trigger[data-founder-field].is-selected,#founder .choice-grid figure.is-selected figcaption,#founder .founder-payment-card.is-selected{border-color:rgba(190,195,200,.62)!important;box-shadow:inset 0 0 0 1px rgba(190,195,200,.38)!important}
#founder .product-viewer-trigger[data-founder-field].is-selected::after{border-color:rgba(210,214,218,.72)!important;background:#d7dade!important;color:#111!important}
#founder .form-consent input{accent-color:#aeb3b8!important}
@media (min-width:901px) and (max-width:1180px) and (orientation:landscape){
#founder .founder-payment-card:not([data-founder-value="HALO PE10-12"]){grid-template-columns:minmax(310px,42%) minmax(0,58%)!important;gap:28px!important}
#founder .founder-payment-card__content,#founder .founder-form{padding:32px!important}
}
@media (max-width:900px),(orientation:portrait) and (max-width:1100px){
#founder .founder-payment-card:not([data-founder-value="HALO PE10-12"]){grid-template-columns:1fr!important;gap:28px!important}
}
@media (max-width:640px){
#founder .founder-payment-card__content,#founder .founder-form{padding:24px 20px!important}
#founder .founder-payment-steps{grid-template-columns:1fr!important;gap:12px!important}
#founder .founder-payment-card:not([data-founder-value="HALO PE10-12"]){gap:22px!important}
}

/* Final sitewide horizontal gutter authority. */
:root{--site-gutter:clamp(64px,5.5vw,80px)!important}
.site-header,.site-footer{padding-left:var(--site-gutter)!important;padding-right:var(--site-gutter)!important}
.content-grid,.split-story,.split-story.reverse,.technical-scroll,#details,#grip,#reel,#proof .proof-grid,#evolution .evolution-grid,#specifications .specifications-grid,#founder .founder-shell,#founder .deposit-intro,#founder .founder-payment-steps,#founder .founder-payment-grid,#founder .halo-allocation-note,#terms .terms-grid,#updates .capture-box{box-sizing:border-box!important;width:calc(100% - (var(--site-gutter) * 2))!important;max-width:1440px!important;margin-left:auto!important;margin-right:auto!important;padding-left:0!important;padding-right:0!important}
#purpose .hero-copy,#assault .assault-copy,#halo .halo-copy{box-sizing:border-box!important;width:100%!important;max-width:none!important;margin-left:0!important;margin-right:0!important;padding-left:var(--site-gutter)!important;padding-right:var(--site-gutter)!important}
@media (max-width:1100px){:root{--site-gutter:24px!important}.site-header,.site-footer{padding-left:var(--site-gutter)!important;padding-right:var(--site-gutter)!important}.content-grid,.split-story,.split-story.reverse,.technical-scroll,#details,#grip,#reel,#proof .proof-grid,#evolution .evolution-grid,#specifications .specifications-grid,#founder .founder-shell,#founder .deposit-intro,#founder .founder-payment-steps,#founder .founder-payment-grid,#founder .halo-allocation-note,#terms .terms-grid,#updates .capture-box{width:calc(100% - (var(--site-gutter) * 2))!important}}
@media (max-width:640px){:root{--site-gutter:20px!important}.site-header,.site-footer{padding-left:var(--site-gutter)!important;padding-right:var(--site-gutter)!important}.content-grid,.split-story,.split-story.reverse,.technical-scroll,#details,#grip,#reel,#proof .proof-grid,#evolution .evolution-grid,#specifications .specifications-grid,#founder .founder-shell,#founder .deposit-intro,#founder .founder-payment-steps,#founder .founder-payment-grid,#founder .halo-allocation-note,#terms .terms-grid,#updates .capture-box{width:calc(100% - (var(--site-gutter) * 2))!important}#purpose .hero-copy,#assault .assault-copy,#halo .halo-copy{padding-left:var(--site-gutter)!important;padding-right:var(--site-gutter)!important}}
